def create_client_from_json(json: str) -> _rust.DefaultClient:
    """Create a new LLM client from a JSON string."""
    return _rust.create_client_from_json(json=json)


def create_client_with_options(options: ClientOptions | None = None) -> _rust.DefaultClient:
    """Create a client from binding-friendly options."""
    _rust_options = _to_rust_client_options(options) if options is not None else _rust.ClientOptions()
    return _rust.create_client_with_options(options=_rust_options)


def decode_data_url(url: str) -> _rust.DecodedDataUrl | None:
    """Decode a base64 data URL into [`DecodedDataUrl`]."""
    return _rust.decode_data_url(url=url)


def encode_data_url(
    bytes: bytes,  # noqa: A002
    mime: str | None = None,
) -> str:
    """Encode bytes as a base64 data URL: `data:<mime>;base64,<b64>`."""
    return _rust.encode_data_url(bytes=bytes, mime=mime)


def ensure_crypto_provider() -> None:
    """Install the `ring` crypto provider as the rustls process default, idempotently."""
    _rust.ensure_crypto_provider()


def exact_model_info(model: str) -> _rust.ModelInfo | None:
    """Look up model metadata only when the requested catalog key exists exactly."""
    return _rust.exact_model_info(model=model)


def install_catalog_overlay_from_str(catalog_json: str) -> None:
    """Install the overlay registry from a raw catalog JSON string, bypassing the network and di."""
    _rust.install_catalog_overlay_from_str(catalog_json=catalog_json)


def model_info(model: str) -> _rust.ModelInfo | None:
    """Look up FFI-friendly pricing and capability metadata for a model."""
    return _rust.model_info(model=model)


def record_cost_usd(system: str, model: str, operation: str, cost_usd: float) -> None:
    """Record the estimated USD cost of a completion."""
    _rust.record_cost_usd(system=system, model=model, operation=operation, cost_usd=cost_usd)


async def refresh_catalog(config: CatalogRefreshConfig | None = None) -> RefreshOutcome:
    """Refresh the runtime catalog overlay per `config`."""
    _rust_config = _to_rust_catalog_refresh_config(config) if config is not None else _rust.CatalogRefreshConfig()
    return await _rust.refresh_catalog(config=_rust_config)


def register_custom_provider(config: CustomProviderConfig) -> None:
    """Register a custom provider in the global runtime registry."""
    _rust.register_custom_provider(config=config)


def unregister_custom_provider(name: str) -> bool:
    """Remove a previously registered custom provider by name."""
    return _rust.unregister_custom_provider(name=name)


async def chat(engine: DefaultClient, req: ChatCompletionRequest) -> ChatCompletionResponse:
    """Chat."""
    _rust_req = _to_rust_chat_completion_request(req)

    if _rust_req is None:
        _rust_req = _rust.ChatCompletionRequest()
    return _from_native_chat_completion_response(await engine.chat(_rust_req))


async def chat_stream(engine: DefaultClient, model: str | ChatCompletionRequest | _rust.ChatCompletionRequest) -> AsyncIterator[ChatCompletionChunk]:
    """Chat stream."""
    if isinstance(model, str):
        req = _rust.ChatCompletionRequest(model=model)
    elif isinstance(model, _rust.ChatCompletionRequest):
        req = model
    elif isinstance(model, ChatCompletionRequest):
        req = _to_rust_chat_completion_request(model)
    else:
        raise TypeError("model must be str or a ChatCompletionRequest request")
    async for item in engine.chat_stream(req):
        yield _from_native_chat_completion_chunk(item)


